namespace ks{namespace{PanelInitializePartialTest partialTest=nullptr;using T=PanelInitializeTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){switch(t.stage()){case S::Hold:return{0x64c,2};case S::SetWake:return{0x64e,2};case S::DispatchWake:return{0x650,4};case S::AwaitWake:return{0x654,2};case S::SetHoldoff:return{0x654,2};case S::WriteHoldoff:return{0x656,6};case S::Restore:return{0x65c,2};case S::SetCount:return{0x68e,2};case S::ClearControl:return{0x690,2};case S::DispatchControl:return{0x692,4};case S::AwaitControl:return{0x696,2};case S::NextControl:return{0x696,2};case S::NextCount:return{0x698,2};case S::RepeatControl:return{0x69a,2};case S::ClearState:return{0x69c,2};case S::ClearDecayMask:return{0x69e,8};case S::ClearDecayInvert:return{0x6a6,8};case S::ClearHoldoff:return{0x6ae,6};case S::ClearPendingMask:return{0x6b4,6};case S::ClearPendingInvert:return{0x6ba,6};case S::ClearInvert:return{0x6c0,6};case S::EnableMask:return{0x6c6,2};case S::WriteMask:return{0x6c8,6};case S::Finish:return{t.kind()==K::Noop?0x64au:t.kind()==K::Wake?0x65eu:0x6ceu,2};default:throw std::runtime_error("Invalid panel initialize stage");}}}
bool PanelInitializeCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x64a||pc==0x64c||pc==0x68e){if(selected)throw std::runtime_error("Overlapping panel initialize");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel initialize capacity");selected->emplace(pc==0x64a?K::Noop:pc==0x64c?K::Wake:K::Reset,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.child()!=T::Child::None)t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Write w,uint8_t value){unsigned at=w==T::Write::Holdoff?0xffec23:w==T::Write::DecayMask?0xffec16:w==T::Write::DecayInvert?0xffec24:w==T::Write::PendingMask?0xffec1b:w==T::Write::PendingInvert?0xffec29:w==T::Write::Invert?0xffec28:0xffec1a;if(w==T::Write::DecayMask||w==T::Write::DecayInvert)f.store32(at,0);else f.store8(at,int8_t(value));});auto hold=[&](auto value){f.push(value);(**selected).depth+=sizeof(value);};auto restore=[&](auto&value){f.pop(value);(**selected).depth-=sizeof(value);};switch(stage){case S::Hold:hold(v[6].r);break;case S::SetWake:f.move(v[6].rl,0xe);break;case S::DispatchWake:f.call(0x8fc);break;case S::SetHoldoff:f.move(v[6].rl,0x19);break;case S::Restore:restore(v[6].r);break;case S::SetCount:f.move(v[0].rl,0x14);break;case S::ClearControl:v[6].r=h.sub16(v[6].r,v[6].r);break;case S::DispatchControl:f.call(0x78c);break;case S::NextControl:f.inc(v[6].rl,1);break;case S::NextCount:f.inc(v[0].rl,-1);break;case S::ClearState:v[0].er=h.sub32(v[0].er,v[0].er);break;case S::EnableMask:f.move(v[0].rl,0xffffffff);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage==S::DispatchWake||stage==S::DispatchControl)h.pc=h.makepc(f.next);else if(stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel initialize clocks differ");return true;}}

